package com.mps.operations.model; import com.mps.organization.model.Organization; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="operational_alerts") public class OperationalAlert {@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="organization_id") private Organization organization;@Column(name="alert_type",nullable=false) private String alertType;@Column(nullable=false) private String severity;@Column(nullable=false) private String status;@Column(nullable=false) private String title;@Column(columnDefinition="text") private String details;@Column(nullable=false) private String source;@Column(name="detected_at",nullable=false) private Instant detectedAt;@Column(name="acknowledged_at") private Instant acknowledgedAt;@Column(name="acknowledged_by") private UUID acknowledgedBy;@Column(name="resolved_at") private Instant resolvedAt;protected OperationalAlert(){}public OperationalAlert(Organization o,String type,String severity,String title,String details,String source){id=UUID.randomUUID();organization=o;alertType=type;this.severity=severity;status="OPEN";this.title=title;this.details=details;this.source=source;detectedAt=Instant.now();}public void acknowledge(UUID actor){status="ACKNOWLEDGED";acknowledgedAt=Instant.now();acknowledgedBy=actor;}public void resolve(){status="RESOLVED";resolvedAt=Instant.now();}public UUID getId(){return id;}public String getAlertType(){return alertType;}public String getSeverity(){return severity;}public String getStatus(){return status;}public String getTitle(){return title;}public String getDetails(){return details;}public String getSource(){return source;}public Instant getDetectedAt(){return detectedAt;}public Instant getAcknowledgedAt(){return acknowledgedAt;}public Instant getResolvedAt(){return resolvedAt;}}
